// goldenErasures lists the erasure patterns of the reconstruct goldens.
// Each returns which shards are kept for a data+parity shape.
var goldenErasures = []struct {
	name string
	keep func(data, parity int, rng *rand.Rand) []bool
}{
	// Exactly data shards, taken from parity first.
	{"parity", func(data, parity int, _ *rand.Rand) []bool {
		return goldenKeepExact(data, parity, 0)
	}},
	// Exactly data shards: 1/16 of the originals, the rest parity.
	{"sixteenth", func(data, parity int, _ *rand.Rand) []bool {
		return goldenKeepExact(data, parity, data/16)
	}},
	// Exactly data shards: a quarter of the originals, the rest parity.
	{"quarter", func(data, parity int, _ *rand.Rand) []bool {
		return goldenKeepExact(data, parity, data/4)
	}},
	// Exactly data shards, uniformly random.
	{"random", func(data, parity int, rng *rand.Rand) []bool {
		keep := make([]bool, data+parity)
		for _, i := range rng.Perm(data + parity)[:data] {
			keep[i] = true
		}
		return keep
	}},
	// Everything except one original.
	{"single", func(data, parity int, _ *rand.Rand) []bool {
		keep := goldenKeep(data, parity, data, parity)
		keep[data/2] = false
		return keep
	}},
	// All originals, half the parity.
	{"parityOnly", func(data, parity int, _ *rand.Rand) []bool {
		return goldenKeep(data, parity, data, parity-(parity+1)/2)
	}},
}

// goldenKeepExact keeps data shards in total: at least nd originals, the
// rest from parity.
func goldenKeepExact(data, parity, nd int) []bool {
	nd = max(nd, data-parity)
	return goldenKeep(data, parity, nd, data-nd)
}

// goldenKeep keeps the first nd originals and the first np parity shards.
func goldenKeep(data, parity, nd, np int) []bool {
	keep := make([]bool, data+parity)
	for i := range nd {
		keep[i] = true
	}
	for i := range np {
		keep[data+i] = true
	}
	return keep
}

