// goldenErased returns shards with the non-kept slots erased. Erased slots
// keep a garbage-filled spare capacity so the decoder cannot rely on zeroed
// output buffers.
func goldenErased(shards [][]byte, keep []bool, rng *rand.Rand) [][]byte {
	out := make([][]byte, len(shards))
	for i, s := range shards {
		if keep[i] {
			out[i] = s
			continue
		}
		g := AllocAligned(1, len(s))[0]
		rng.Read(g)
		out[i] = g[:0]
	}
	return out
}

func goldenDigestAll(shards [][]byte) string {
	h := sha256.New()
	for _, s := range shards {
		h.Write(s)
	}
	return hex.EncodeToString(h.Sum(nil))
}

func TestLeopardGF16ReconstructGolden(t *testing.T) {
	variants := []struct {
		name string
		opts []Option
		fast bool
	}{
		{"default", nil, true},
		{"noNEON", []Option{WithNEON(false)}, false},
	}
	variants = append(variants, goldenArchVariants()...)
	for _, sh := range goldenReconstructShapes {
		shards := goldenShards(sh.data, sh.parity, sh.size, false)
		enc, err := New(sh.data, sh.parity, WithLeopardGF16(true))
		if err != nil {
			t.Fatal(err)
		}
		if err := enc.Encode(shards); err != nil {
			t.Fatal(err)
		}
		for _, v := range variants {
			if testing.Short() && sh.size > 4096 && !v.fast {
				continue
			}
			enc, err := New(sh.data, sh.parity, append([]Option{WithLeopardGF16(true)}, v.opts...)...)
			if err != nil {
				t.Fatal(err)
			}
			for ei, e := range goldenErasures {
				rng := rand.New(rand.NewSource(int64(sh.data*7919 + sh.parity*31 + ei)))
				keep := e.keep(sh.data, sh.parity, rng)
				for _, all := range []bool{false, true} {
					in := goldenErased(shards, keep, rng)
					want := sh.dataDigests[ei]
					if all {
						err = enc.Reconstruct(in)
						want = sh.allDigests[ei]
					} else {
						err = enc.ReconstructData(in)
						in = in[:sh.data]
					}
					if err != nil {
						t.Fatal(err)
					}
					got := goldenDigestAll(in)
					if got != want {
						t.Errorf("%d+%d size=%d %s %s all=%v: digest %s, want %s", sh.data, sh.parity, sh.size, v.name, e.name, all, got, want)
					}
				}
			}
		}
	}
}
